typedef enum
{
	PGEVT_REGISTER,
	PGEVT_CONNRESET,
	PGEVT_CONNDESTROY,
	PGEVT_RESULTCREATE,
	PGEVT_RESULTCOPY,
	PGEVT_RESULTDESTROY
} PGEventId;

typedef struct
{
	const PGresult *src;
	PGresult   *dest;
} PGEventResultCopy;

typedef enum
{
	PGRES_POLLING_FAILED = 0,
	PGRES_POLLING_READING,
	PGRES_POLLING_WRITING,
	PGRES_POLLING_OK,
	PGRES_POLLING_ACTIVE
} PostgresPollingStatusType;

typedef enum
{
	PQTRANS_IDLE,
	PQTRANS_ACTIVE,
	PQTRANS_INTRANS,
	PQTRANS_INERROR,
	PQTRANS_UNKNOWN
} PGTransactionStatusType;

typedef enum
{
	PQERRORS_TERSE,
	PQERRORS_DEFAULT,
	PQERRORS_VERBOSE,
	PQERRORS_SQLSTATE
} PGVerbosity;

typedef enum
{
	PQSHOW_CONTEXT_NEVER,
	PQSHOW_CONTEXT_ERRORS,
	PQSHOW_CONTEXT_ALWAYS
} PGContextVisibility;

typedef enum
{
	PQPING_OK,
	PQPING_REJECT,
	PQPING_NO_RESPONSE,
	PQPING_NO_ATTEMPT
} PGPing;

typedef enum
{
	PQ_PIPELINE_OFF,
	PQ_PIPELINE_ON,
	PQ_PIPELINE_ABORTED
} PGpipelineStatus;

typedef struct pgNotify
{
	char	   *relname;		/* notification condition name */
	int			be_pid;			/* process ID of notifying server process */
	char	   *extra;			/* notification parameter */
	/* Fields below here are private to libpq; apps should not use 'em */
	struct pgNotify *next;		/* list link */
} PGnotify;

typedef struct _PQprintOpt
{
	pqbool		header;
	pqbool		align;
	pqbool		standard;
	pqbool		html3;
	pqbool		expanded;
	pqbool		pager;
	char	   *fieldSep;
	char	   *tableOpt;
	char	   *caption;
	char	  **fieldName;
} PQprintOpt;

typedef struct _PQconninfoOption
{
	char	   *keyword;
	char	   *envvar;
	char	   *compiled;
	char	   *val;
	char	   *label;
	char	   *dispchar;
	int			dispsize;
} PQconninfoOption;

typedef struct
{
	int			len;
	int			isint;
	union
	{
		int	   *ptr;
		int			integer;
	}			u;
} PQArgBlock;

typedef struct pgresAttDesc
{
	char	   *name;
	Oid			tableid;
	int			columnid;
	int			format;
	Oid			typid;
	int			typlen;
	int			atttypmod;
} PGresAttDesc;

typedef struct _PGpromptOAuthDevice
{
	const char *verification_uri;
	const char *user_code;
	const char *verification_uri_complete;
	int			expires_in;
} PGpromptOAuthDevice;

typedef struct PGoauthBearerRequest
{
	/* Hook inputs (constant across all calls) */
	const char *openid_configuration;
	const char *scope;

	/* Hook outputs */
	PostgresPollingStatusType (*async) (PGconn *conn,
										struct PGoauthBearerRequest *request,
										PQ_SOCKTYPE * altsock);
	void		(*cleanup) (PGconn *conn, struct PGoauthBearerRequest *request);
	char	   *token;
	void	   *user;
} PGoauthBearerRequest;

