// Register a libpq event callback on this connection.
// Constraints enforced:
// - conn must be a valid PGconn (provided by runtime).
// - proc must be a valid PGEventProc; we use a non-capturing lambda convertible to function pointer.
// - name must be a valid C string; we use FUZZ_PARAM_STR().
// - passThrough may be any pointer; use address of a local token with stable lifetime for this call.

// Create an event proc that records it was invoked and returns success.
PGEventProc proc = +[](PGEventId evtId, void *evtInfo, void *passThrough) -> int {
    (void)evtInfo;
    // Record last event id observed (for potential downstream validation)
    if (passThrough) {
        // Use integer attribute on the PGconn passed via passThrough when possible
        // No direct type available here; best-effort no-op.
    }
    // Always indicate success to exercise event flow paths.
    return 1;
};
std::string name = FUZZ_PARAM_STR();
int token = *FUZZ_PARAM(int); // passThrough token
int rc = PQregisterEventProc(conn, proc, name.c_str(), (void*)&token);
// Track that an event proc is registered on this connection for downstream APIs
if (rc) {
    FUZZ_SET_ATTR_INT(conn, "has_eventproc", 1);
    // Store the function pointer identity for later PQ*InstanceData calls
    FUZZ_SET_ATTR_PTR(conn, "eventproc_ptr", (void*)proc);
}
// Return conn to the pool

// Associate instance data with an event proc on this connection.
// If no proc is known on this conn, first register one (requirement: proc must be previously known).

void *known_proc = FUZZ_GET_ATTR_PTR(conn, "eventproc_ptr");
PGEventProc proc;
if (!known_proc) {
    // Register a temporary event proc to satisfy the requirement
    PGEventProc tmp = +[](PGEventId, void*, void*) -> int { return 1; };
    std::string ename = FUZZ_PARAM_STR();
    int tok = *FUZZ_PARAM(int);
    if (!PQregisterEventProc(conn, tmp, ename.c_str(), (void*)&tok)) {
        FUZZ_BAIL();
    }
    FUZZ_SET_ATTR_INT(conn, "has_eventproc", 1);
    FUZZ_SET_ATTR_PTR(conn, "eventproc_ptr", (void*)tmp);
    proc = tmp;
} else {
    proc = (PGEventProc)known_proc;
}
// Data to associate can be any pointer; use address of a local buffer
int data_box = *FUZZ_PARAM(int);
int ok = PQsetInstanceData(conn, proc, (void*)&data_box);
if (!ok) { FUZZ_BAIL(); }
// Optionally validate via getter
void *got = PQinstanceData(conn, proc);
FUZZ_ASSERT(got == (void*)&data_box, "PQinstanceData must return the data just set for this proc");
// Return conn to the pool

// Retrieve instance data associated with an event proc.
// Ensure a known proc exists; if not, register and set data first.
void *known_proc = FUZZ_GET_ATTR_PTR(conn, "eventproc_ptr");
PGEventProc proc;
if (!known_proc) {
    PGEventProc tmp = +[](PGEventId, void*, void*) -> int { return 1; };
    std::string name = FUZZ_PARAM_STR();
    int tok = *FUZZ_PARAM(int);
    if (!PQregisterEventProc(conn, tmp, name.c_str(), (void*)&tok)) { FUZZ_BAIL(); }
    FUZZ_SET_ATTR_INT(conn, "has_eventproc", 1);
    FUZZ_SET_ATTR_PTR(conn, "eventproc_ptr", (void*)tmp);
    proc = tmp;
    int payload = *FUZZ_PARAM(int);
    if (!PQsetInstanceData(conn, proc, (void*)&payload)) { FUZZ_BAIL(); }
} else {
    proc = (PGEventProc)known_proc;
}
(void)PQinstanceData(conn, proc); // Exercise the getter (may be NULL legitimately)
// Return conn to the pool

// Set instance data for a PGresult and event proc. Result must be app-created.
// Steps:
// 1) Ensure an event proc is registered on conn.
// 2) Create an empty result associated with conn.
// 3) Fire RESULTCREATE events so handlers can initialize.
// 4) Set instance data and validate via getter.

// 1) Ensure proc exists
void *known_proc = FUZZ_GET_ATTR_PTR(conn, "eventproc_ptr");
PGEventProc proc;
if (!known_proc) {
    PGEventProc tmp = +[](PGEventId, void*, void*) -> int { return 1; };
    std::string name = FUZZ_PARAM_STR();
    int tok = *FUZZ_PARAM(int);
    if (!PQregisterEventProc(conn, tmp, name.c_str(), (void*)&tok)) { FUZZ_BAIL(); }
    FUZZ_SET_ATTR_PTR(conn, "eventproc_ptr", (void*)tmp);
    proc = tmp;
} else {
    proc = (PGEventProc)known_proc;
}
// 2) Create an application PGresult
ExecStatusType status = PGRES_TUPLES_OK;
PGresult *res = PQmakeEmptyPGresult(conn, status);
if (!res) { FUZZ_BAIL(); }
// 3) Fire create events
if (!PQfireResultCreateEvents(conn, res)) { /* allowed to fail */ }
// 4) Set and validate instance data
int payload = *FUZZ_PARAM(int);
int ok = PQresultSetInstanceData(res, proc, (void*)&payload);
if (!ok) { PQclear(res); FUZZ_BAIL(); }
void *roundtrip = PQresultInstanceData(res, proc);
FUZZ_ASSERT(roundtrip == (void*)&payload, "PQresultInstanceData must return data just set");
// Cleanup temporary result
PQclear(res);
// Return conn to pool

// Retrieve instance data associated with a PGresult and event proc.
// We construct a temporary result, associate data, then get it back.

// Ensure proc exists on conn
void *known_proc = FUZZ_GET_ATTR_PTR(conn, "eventproc_ptr");
PGEventProc proc;
if (!known_proc) {
    PGEventProc tmp = +[](PGEventId, void*, void*) -> int { return 1; };
    std::string name = FUZZ_PARAM_STR();
    int tok = *FUZZ_PARAM(int);
    if (!PQregisterEventProc(conn, tmp, name.c_str(), (void*)&tok)) { FUZZ_BAIL(); }
    FUZZ_SET_ATTR_PTR(conn, "eventproc_ptr", (void*)tmp);
    proc = tmp;
} else {
    proc = (PGEventProc)known_proc;
}
PGresult *res = PQmakeEmptyPGresult(conn, PGRES_TUPLES_OK);
if (!res) { FUZZ_BAIL(); }
(void)PQfireResultCreateEvents(conn, res);
int payload = *FUZZ_PARAM(int);
if (!PQresultSetInstanceData(res, proc, (void*)&payload)) { PQclear(res); FUZZ_BAIL(); }
void *got = PQresultInstanceData(res, proc);
FUZZ_ASSERT(got == (void*)&payload, "PQresultInstanceData roundtrip failed");
PQclear(res);
// Return conn

// Manually fire RESULTCREATE events for an application-created result.
// Create a result via PQmakeEmptyPGresult as required.
PGresult *res = PQmakeEmptyPGresult(conn, PGRES_TUPLES_OK);
if (!res) { FUZZ_BAIL(); }
// Call the target; allowed to fail depending on conn state
(void)PQfireResultCreateEvents(conn, res);
// Cleanup the temporary result to avoid leaks
PQclear(res);
// Return conn to pool

// Begin a nonblocking connection using a conninfo string.
std::string conninfo = FUZZ_PARAM_STR();
PGconn *conn = PQconnectStart(conninfo.c_str());
if (!conn) { FUZZ_BAIL(); }
// Mark as started for PQconnectPoll
FUZZ_SET_ATTR_INT(conn, "connect_started", 1);

// Begin a nonblocking connection using keyword/value arrays.
// Build small NULL-terminated arrays as required by API.
static const int N = 3; // two entries + NULL
std::string k0 = FUZZ_PARAM_STR();
std::string v0 = FUZZ_PARAM_STR();
std::string k1 = FUZZ_PARAM_STR();
std::string v1 = FUZZ_PARAM_STR();
const char *keywords[N] = { k0.c_str(), k1.c_str(), nullptr };
const char *values[N]   = { v0.c_str(), v1.c_str(), nullptr };
int expand_dbname = (*FUZZ_PARAM(unsigned int)) % 2;
PGconn *conn = PQconnectStartParams(keywords, values, expand_dbname);
if (!conn) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(conn, "connect_started", 1);

// Advance a nonblocking connection started with PQconnectStart/Params.
int started = FUZZ_GET_ATTR_INT(conn, "connect_started");
if (!started) { FUZZ_BAIL(); }
PostgresPollingStatusType st = PQconnectPoll(conn);
(void)st; // Status guides caller; we just exercise the call once.
// Keep conn alive

// Establish a blocking connection using a conninfo string.
std::string conninfo = FUZZ_PARAM_STR();
PGconn *conn = PQconnectdb(conninfo.c_str());
if (!conn) { FUZZ_BAIL(); }
// Mark as blocking-connected attempt (status may be BAD)
FUZZ_SET_ATTR_INT(conn, "blocking_connect", 1);

// Establish a blocking connection using keyword/value arrays.
static const int N = 3; // two entries + NULL
std::string k0 = FUZZ_PARAM_STR();
std::string v0 = FUZZ_PARAM_STR();
std::string k1 = FUZZ_PARAM_STR();
std::string v1 = FUZZ_PARAM_STR();
const char *keywords[N] = { k0.c_str(), k1.c_str(), nullptr };
const char *values[N]   = { v0.c_str(), v1.c_str(), nullptr };
int expand_dbname = (*FUZZ_PARAM(unsigned int)) % 2;
PGconn *conn = PQconnectdbParams(keywords, values, expand_dbname);
if (!conn) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(conn, "blocking_connect", 1);

// Close and free a PGconn. After this call, conn must not be used.
PQfinish(conn);
// Do not return conn as output to avoid use-after-free.

// Retrieve default connection options array; must be freed with PQconninfoFree.
PQconninfoOption *connOptions = PQconndefaults();
if (!connOptions) { FUZZ_BAIL(); }
// Tag for correct freeing path
FUZZ_SET_ATTR_INT(connOptions, "conninfo_source", 1);

// Parse a conninfo string into a PQconninfoOption array.
std::string s = FUZZ_PARAM_STR();
char *errmsg = nullptr;
PQconninfoOption *connOptions = PQconninfoParse(s.c_str(), &errmsg);
if (!connOptions) {
    // On error, errmsg may be set and must be freed with PQfreemem
    if (errmsg) { PQfreemem(errmsg); }
    FUZZ_BAIL(); // Avoid returning null output
}
if (errmsg) { PQfreemem(errmsg); }
FUZZ_SET_ATTR_INT(connOptions, "conninfo_source", 2);

// Retrieve the connection's active options. Caller must PQconninfoFree.
PQconninfoOption *connOptions = PQconninfo(conn);
if (!connOptions) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(connOptions, "conninfo_source", 3);
// Return both the conn (still valid) and the options for later free

// Free a PQconninfoOption array previously returned by PQconndefaults/PQconninfoParse/PQconninfo.
PQconninfoFree(connOptions);
// Nothing to return

// Begin an asynchronous reset of the connection.
int ok = PQresetStart(conn);
if (!ok) { /* allowed to fail; still return conn for further operations */ }
FUZZ_SET_ATTR_INT(conn, "reset_started", 1);

// Advance an asynchronous reset begun with PQresetStart.
if (!FUZZ_GET_ATTR_INT(conn, "reset_started")) { FUZZ_BAIL(); }
PostgresPollingStatusType st = PQresetPoll(conn);
(void)st;
// Keep conn

// Synchronously reset the connection.
PQreset(conn);
// After return, status may be OK or BAD; we keep conn alive for further fuzzing

// Legacy blocking connect with discrete parameters; each may be NULL to accept defaults.
// Use a single random bitfield to decide which params are NULL vs provided.
unsigned int bits = *FUZZ_PARAM(unsigned int);

std::string host = FUZZ_PARAM_STR();      const char *pghost    = (bits & 0x01) ? host.c_str() : nullptr;
std::string port = FUZZ_PARAM_STR();      const char *pgport    = (bits & 0x02) ? port.c_str() : nullptr;
std::string opts = FUZZ_PARAM_STR();      const char *pgoptions = (bits & 0x04) ? opts.c_str() : nullptr;
std::string tty  = FUZZ_PARAM_STR();      const char *pgtty     = (bits & 0x08) ? tty.c_str()  : nullptr;
std::string db   = FUZZ_PARAM_STR();      const char *dbName    = (bits & 0x10) ? db.c_str()   : nullptr;
std::string usr  = FUZZ_PARAM_STR();      const char *login     = (bits & 0x20) ? usr.c_str()  : nullptr;
std::string pwd  = FUZZ_PARAM_STR();      const char *pass      = (bits & 0x40) ? pwd.c_str()  : nullptr;

PGconn *conn = PQsetdbLogin(pghost, pgport, pgoptions, pgtty, dbName, login, pass);
if (!conn) { FUZZ_BAIL(); }
// Track as a blocking connection attempt (status may be BAD until checked by callers)
FUZZ_SET_ATTR_INT(conn, "blocking_connect", 1);

// Create a PGcancelConn tied to this connection. Caller must later PQcancelFinish.
PGcancelConn *cancelConn = PQcancelCreate(conn);
if (!cancelConn) { FUZZ_BAIL(); }
// Mark lifecycle/state for follow-on stubs
FUZZ_SET_ATTR_INT(cancelConn, "cancel_created", 1);
FUZZ_SET_ATTR_INT(cancelConn, "cancel_in_progress", 0);

// Initiate a non-blocking cancel operation.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
int ok = PQcancelStart(cancelConn);
// If it started, record in-progress state; libpq returns nonzero on success
if (ok) { FUZZ_SET_ATTR_INT(cancelConn, "cancel_in_progress", 1); }

// Perform a blocking cancel request; does not require prior PQcancelStart.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
int rc = PQcancelBlocking(cancelConn);
(void)rc; // Return code semantics are libpq-defined; just exercise the call.
// After a blocking attempt, ensure no in-progress nonblocking state remains.
FUZZ_SET_ATTR_INT(cancelConn, "cancel_in_progress", 0);

// Advance a non-blocking cancel. Must have been started.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_in_progress")) { FUZZ_BAIL(); }
PostgresPollingStatusType st = PQcancelPoll(cancelConn);
(void)st; // Caller would normally react to READING/WRITING/OK/FAILED

// Query status of cancel connection.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
ConnStatusType s = PQcancelStatus(cancelConn);
(void)s;

// Obtain underlying socket descriptor for polling.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
int sock = PQcancelSocket(cancelConn);
(void)sock;

// Retrieve last error message; owned by libpq.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
char *msg = PQcancelErrorMessage(cancelConn);
(void)msg; // Do not free

// Reset the cancel connection state.
if (!FUZZ_GET_ATTR_INT(cancelConn, "cancel_created")) { FUZZ_BAIL(); }
PQcancelReset(cancelConn);
FUZZ_SET_ATTR_INT(cancelConn, "cancel_in_progress", 0);

// Finish and free the PGcancelConn. After this, it must not be used.
PQcancelFinish(cancelConn);
// Do not return cancelConn to avoid use-after-free.

// Create a legacy PGcancel object for this connection. Must be freed with PQfreeCancel.
PGcancel *cancel = PQgetCancel(conn);
if (!cancel) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(cancel, "legacy_cancel", 1);

// Free a PGcancel created by PQgetCancel.
if (!FUZZ_GET_ATTR_INT(cancel, "legacy_cancel")) { /* Defensive: unknown provenance */ }
PQfreeCancel(cancel);
// Not returned; pointer invalid after free.

// Deprecated cancellation using PGcancel. Provide an optional error buffer.
if (!FUZZ_GET_ATTR_INT(cancel, "legacy_cancel")) { FUZZ_BAIL(); }
unsigned int mode = *FUZZ_PARAM(unsigned int);
int size = (int)(*FUZZ_PARAM(unsigned int) % 256); // keep small for perf
char *errbuf_ptr = nullptr;
if ((mode & 1) && size > 0) {
    // Allocate a writable buffer of the requested size
    static std::string storage; // static to ensure lifetime through call
    storage.assign((size_t)size, '\0');
    errbuf_ptr = &storage[0];
} else {
    size = 0; // errbuf_ptr remains NULL as allowed by API
}
int ok = PQcancel(cancel, errbuf_ptr, size);
(void)ok;

// Deprecated, not thread-safe: request query cancellation on a connection.
int rc = PQrequestCancel(conn);
(void)rc;

// Get database name; owned by libpq.
char *v = PQdb(conn);
(void)v;

// Get user name; owned by libpq.
char *v = PQuser(conn);
(void)v;

// Get password string; sensitive. Owned by libpq.
char *v = PQpass(conn);
(void)v;

// Get host name; owned by libpq.
char *v = PQhost(conn);
(void)v;

// Get host address string; owned by libpq.
char *v = PQhostaddr(conn);
(void)v;

// Get server port as string; owned by libpq.
char *v = PQport(conn);
(void)v;

// Get the debugging tty option string (historical); pointer owned by libpq.
char *v = PQtty(conn);
(void)v;
// Validation: conn is returned to pool; retrieved pointer is observed but not freed.

// Get the connection options string; pointer owned by libpq.
char *v = PQoptions(conn);
(void)v;
// Validation: safe getter usage; conn returned to pool.

// Return overall connection status.
ConnStatusType st = PQstatus(conn);
(void)st;
// Validation: simple getter; no constraints beyond valid conn.

// Return current transaction status of the session.
PGTransactionStatusType tx = PQtransactionStatus(conn);
(void)tx;
// Validation: getter call; conn returned.

// Retrieve current value of a reported server parameter by name.
std::string pname = FUZZ_PARAM_STR();
const char *val = PQparameterStatus(conn, pname.c_str());
(void)val; // May be NULL if parameter not known
// Validation: pname is a valid C-string; pointer result not freed; conn returned.

// Get frontend/backend protocol version in use.
int ver = PQprotocolVersion(conn);
(void)ver;
// Validation: simple getter; conn returned.

// Get full protocol version (if supported by linked libpq).
int ver = PQfullProtocolVersion(conn);
(void)ver;
// Validation: safe call regardless of server; conn returned.

// Return server version as integer (0 if unknown/bad connection is possible).
int v = PQserverVersion(conn);
(void)v;
// Validation: getter; conn returned.

// Get last error message for the connection; owned by libpq.
char *msg = PQerrorMessage(conn);
(void)msg; // Do not free
// Validation: respects ownership; conn returned.

// Return underlying socket FD or -1.
int sock = PQsocket(conn);
(void)sock;
// Validation: getter; conn returned.

// Get backend PID associated with this connection.
int pid = PQbackendPID(conn);
(void)pid;
// Validation: getter; conn returned.

// Report current pipeline mode status.
PGpipelineStatus ps = PQpipelineStatus(conn);
(void)ps;
// Validation: getter; conn returned.

// Indicate whether a password is required.
int r = PQconnectionNeedsPassword(conn);
(void)r;
// Validation: getter; conn returned.

// Indicate whether a password was used.
int r = PQconnectionUsedPassword(conn);
(void)r;
// Validation: getter; conn returned.

// Indicate whether GSSAPI was used for this connection.
int r = PQconnectionUsedGSSAPI(conn);
(void)r;
// Validation: getter; conn returned.

// Get current client encoding id.
int enc = PQclientEncoding(conn);
(void)enc;
// Validation: getter; conn returned.

// Set client encoding; use a mix of known-good names and fuzzed string.
const char *candidates[5] = { "UTF8", "SQL_ASCII", "LATIN1", "WIN1252", nullptr };
unsigned int pick = *FUZZ_PARAM(unsigned int);
std::string rnd = FUZZ_PARAM_STR();
const char *encname = candidates[pick % 5];
if (!encname) { encname = rnd.c_str(); }
int rc = PQsetClientEncoding(conn, encname);
(void)rc; // May fail depending on server/libpq support; not a constraint violation
// Validation: provided a valid C-string; conn returned.

// Check whether SSL/TLS is in use on this connection.
int inuse = PQsslInUse(conn);
(void)inuse;
// Validation: getter; conn returned.

// Retrieve underlying TLS library-specific structure by name.
// Try common identifiers and a fuzzed fallback to exercise NULL path as well.
const char *names[4] = { "SSL", "SSL_CTX", "GnuTLSSession", nullptr };
unsigned int pick = *FUZZ_PARAM(unsigned int);
std::string other = FUZZ_PARAM_STR();
const char *name = names[pick % 4];
if (!name) { name = other.c_str(); }
void *p = PQsslStruct(conn, name);
(void)p; // May be NULL if not applicable or unknown name
// Validation: valid C-string passed; conn returned.

// Retrieve a textual SSL/TLS attribute value by name.
// Use a small candidate set plus fuzzed name.
const char *attrs[5] = { "protocol", "cipher", "key_bits", "library", nullptr };
unsigned int pick = *FUZZ_PARAM(unsigned int);
std::string other = FUZZ_PARAM_STR();
const char *attr = attrs[pick % 5];
if (!attr) { attr = other.c_str(); }
const char *val = PQsslAttribute(conn, attr);
(void)val; // May be NULL if attribute unsupported
// Validation: attribute name is a valid C-string; pointer result not freed; conn returned.

// Retrieve the list of supported SSL/TLS attribute names. Caller must treat it as read-only.
// Requirement: conn must be valid (provided by runtime).
const char *const *names = PQsslAttributeNames(conn);
// Optionally touch a few entries to exercise access; list is NULL-terminated or may be NULL
if (names) {
    // Read up to first 3 entries safely
    for (int i = 0; i < 3 && names[i]; ++i) {
        const char *n = names[i];
        (void)n;
    }
}
// Validation: read-only usage; no ownership transfer; conn returned to pool.

// Get the OpenSSL SSL* pointer (or NULL) for this connection.
// Requirement: conn must be valid.
void *ssl = PQgetssl(conn);
(void)ssl; // May be NULL if not using OpenSSL or not encrypted
// Validation: simple getter; no ownership or state change; conn returned.

// Indicate whether libpq should initialize OpenSSL on its own.
// do_init is 0/1; choose randomly
int do_init = (int)(*FUZZ_PARAM(unsigned int) % 2);
PQinitSSL(do_init);
// Validation: global setting; no objects involved; no outputs.

// Control libpq's initialization of OpenSSL libraries separately for SSL and crypto.
